create function private.advance_balance(a uuid) returns bigint language sql stable set search_path='' as $$ select coalesce((select sum((metadata->>'amount_minor')::bigint) from public.financial_events where source_id=a and event_type in ('ADVANCE','ADVANCE_TOPUP') and status='POSTED'),0)-coalesce((select sum(l.amount_minor) from public.advance_expense_links l join public.purchase_funding_allocations f on f.id=l.purchase_funding_allocation_id join public.purchases p on p.id=f.purchase_id join public.financial_events e on e.id=p.financial_event_id where l.advance_id=a and e.status='POSTED'),0)-coalesce((select sum(r.amount_minor) from public.advance_returns r join public.financial_events e on e.id=r.financial_event_id where r.advance_id=a and e.status='POSTED'),0)+coalesce((select sum((ra->>'amount_minor')::bigint) from public.refunds rf join public.financial_events fe on fe.id=rf.financial_event_id cross join lateral jsonb_array_elements(rf.allocations) ra where fe.status='POSTED' and ra->>'destination'='ADVANCE' and ra->>'advance_id'=a::text),0) $$;
create function private.bill_balance(b uuid) returns bigint language sql stable set search_path='' as $$ select coalesce((select total_minor from public.bills where id=b and financial_event_id is not null and status not in ('draft','submitted','cancelled')),0)-coalesce((select sum(p.amount_minor) from public.bill_payments p join public.financial_events e on e.id=p.financial_event_id where p.bill_id=b and e.status='POSTED'),0)-coalesce((select sum(r.amount_minor) from public.refunds r join public.financial_events e on e.id=r.financial_event_id where r.bill_id=b and e.status='POSTED'),0) $$;
create function private.claim_balance(c uuid) returns bigint language sql stable set search_path='' as $$
select greatest(0,least(cl.approved_minor-coalesce((select sum(rp.amount_minor) from public.reimbursement_payments rp join public.financial_events e on e.id=rp.financial_event_id where rp.reimbursement_claim_id=c and e.status='POSTED'),0),
coalesce((select sum(greatest(0,least(ci.claimed_minor-coalesce((select sum(sa.amount_minor) from public.settlement_allocations sa join public.financial_events e on e.id=sa.event_id where sa.source_allocation_id=ci.purchase_funding_allocation_id and sa.kind='PAYMENT' and e.source_id=c and e.status='POSTED'),0),private.source_outstanding(ci.purchase_funding_allocation_id)))) from public.reimbursement_claim_items ci where ci.reimbursement_claim_id=c),0)))::bigint from public.reimbursement_claims cl where cl.id=c $$;
create function private.request_remaining(r uuid) returns bigint language sql stable set search_path='' as $$ select greatest(0,q.estimated_minor-coalesce((select sum(total_minor) from (select total_minor from public.purchases where linked_request_id=r and status='posted' union all select total_minor from public.bills where linked_request_id=r and financial_event_id is not null and status<>'cancelled') f),0))::bigint from public.purchase_requests q where q.id=r $$;
create function private.budget_check(p uuid,cat uuid,n bigint,dt date,req uuid default null) returns void language plpgsql set search_path='' as $$ declare l record; actual bigint; reserved bigint; begin if cat is null then return; end if; for l in select bl.*,b.start_date,b.end_date from public.budget_lines bl join public.budgets b on b.id=bl.budget_id where bl.project_id=p and bl.category_id=cat and bl.hard_stop and b.status='active' and dt between b.start_date and b.end_date for update of bl loop select coalesce(sum(case when le.direction='DEBIT' then le.amount_minor else -le.amount_minor end),0) into actual from public.ledger_entries le join public.financial_accounts a on a.id=le.account_id join public.financial_events e on e.id=le.financial_event_id where le.project_id=p and le.category_id=cat and a.account_type='EXPENSE' and e.event_date between l.start_date and l.end_date; select coalesce(sum(private.request_remaining(r.id)),0) into reserved from public.purchase_requests r where r.project_id=p and r.status='approved' and r.category_id=cat and r.id is distinct from req; if actual+reserved+n>l.planned_minor then raise exception 'BUDGET_EXCEEDED'; end if; end loop; end $$;
create function public.save_purchase(p_project uuid,p_data jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare v_purchase_id uuid:=coalesce((p_data->>'id')::uuid,gen_random_uuid()); currency text; total bigint:=0; subtotal bigint:=0; tax bigint:=0; discount bigint:=0; shipping bigint:=coalesce((p_data->>'shipping_minor')::bigint,0); item jsonb; alloc jsonb; line bigint; q numeric; existing public.purchases; begin if not private.member(p_project) or private.role(p_project,array['VIEWER']::public.project_role[]) then raise exception 'PERMISSION_DENIED'; end if; perform 1 from public.projects where projects.id=p_project and (status in ('active','paused') or (status='closed' and private.role(p_project,array['OWNER','ADMIN']::public.project_role[]) and length(coalesce(p_data->>'notes',''))>=5 and exists(select 1 from public.financial_events where id=(p_data->>'corrects_event_id')::uuid and project_id=p_project and event_type='PURCHASE' and status='REVERSED'))) for update; if not found then raise exception 'PROJECT_CLOSED'; end if; select * into existing from public.purchases where purchases.id=v_purchase_id for update; if existing.id is not null then if existing.project_id<>p_project or existing.status not in ('draft','needs_info') or (existing.created_by<>auth.uid() and not private.finance(p_project)) then raise exception 'DRAFT_NOT_EDITABLE'; end if; if existing.version<>coalesce((p_data->>'version')::integer,existing.version) then raise exception 'STALE_DRAFT'; end if; delete from public.purchase_funding_allocations where purchase_id=v_purchase_id; delete from public.purchase_items where purchase_id=v_purchase_id; end if; select projects.currency into currency from public.projects where projects.id=p_project;
if jsonb_array_length(p_data->'items')<1 then raise exception 'ITEMS_REQUIRED'; end if;
for item in select * from jsonb_array_elements(p_data->'items') loop q:=(item->>'quantity')::numeric; if q<=0 or q<>round(q,6) or (item->>'unit_price_minor')::bigint<0 then raise exception 'INVALID_ITEM'; end if; line:=round(q*(item->>'unit_price_minor')::bigint)::bigint; subtotal:=subtotal+line; tax:=tax+coalesce((item->>'tax_minor')::bigint,0); discount:=discount+coalesce((item->>'discount_minor')::bigint,0); end loop;
total:=subtotal+tax+shipping-discount; if total<=0 or shipping<0 or tax<0 or discount<0 then raise exception 'INVALID_TOTAL'; end if;
insert into public.purchases(id,project_id,vendor_id,purchase_date,invoice_number,subtotal_minor,tax_minor,shipping_minor,discount_minor,total_minor,currency,category_id,purchased_by_user_id,notes,linked_request_id,created_by) values(v_purchase_id,p_project,(p_data->>'vendor_id')::uuid,coalesce((p_data->>'date')::date,current_date),nullif(p_data->>'invoice_number',''),subtotal,tax,shipping,discount,total,currency,(p_data->>'category_id')::uuid,coalesce((p_data->>'purchased_by_user_id')::uuid,auth.uid()),p_data->>'notes',(p_data->>'linked_request_id')::uuid,auth.uid()) on conflict on constraint purchases_pkey do update set vendor_id=excluded.vendor_id,purchase_date=excluded.purchase_date,invoice_number=excluded.invoice_number,subtotal_minor=excluded.subtotal_minor,tax_minor=excluded.tax_minor,shipping_minor=excluded.shipping_minor,discount_minor=excluded.discount_minor,total_minor=excluded.total_minor,category_id=excluded.category_id,purchased_by_user_id=excluded.purchased_by_user_id,notes=excluded.notes,linked_request_id=excluded.linked_request_id,version=purchases.version+1;
for item in select * from jsonb_array_elements(p_data->'items') loop insert into public.purchase_items(project_id,purchase_id,description,quantity,unit,unit_price_minor,tax_minor,discount_minor,line_total_minor,category_id,mark_as_asset) values(p_project,v_purchase_id,item->>'description',(item->>'quantity')::numeric,coalesce(item->>'unit','each'),(item->>'unit_price_minor')::bigint,coalesce((item->>'tax_minor')::bigint,0),coalesce((item->>'discount_minor')::bigint,0),round((item->>'quantity')::numeric*(item->>'unit_price_minor')::bigint)::bigint+coalesce((item->>'tax_minor')::bigint,0)-coalesce((item->>'discount_minor')::bigint,0),coalesce((item->>'category_id')::uuid,(p_data->>'category_id')::uuid),coalesce((item->>'mark_as_asset')::boolean,false)); end loop;
for alloc in select * from jsonb_array_elements(p_data->'allocations') loop if alloc->>'source_type'='MEMBER' and not exists(select 1 from public.project_members where project_id=p_project and user_id=(alloc->>'member_user_id')::uuid and is_active) then raise exception 'INVALID_MEMBER'; end if; insert into public.purchase_funding_allocations(project_id,purchase_id,source_type,project_account_id,member_user_id,advance_id,funding_source_id,amount_minor,currency) values(p_project,v_purchase_id,alloc->>'source_type',(alloc->>'project_account_id')::uuid,(alloc->>'member_user_id')::uuid,(alloc->>'advance_id')::uuid,(alloc->>'funding_source_id')::uuid,(alloc->>'amount_minor')::bigint,currency); end loop;
update public.purchases set corrects_event_id=(p_data->>'corrects_event_id')::uuid,purpose=p_data->>'purpose',tags=coalesce(array(select jsonb_array_elements_text(p_data->'tags')),'{}'),payment_method=p_data->>'payment_method',transaction_reference=p_data->>'transaction_reference' where purchases.id=v_purchase_id; perform private.log(p_project,'purchase_saved','purchases',v_purchase_id); return v_purchase_id; end $$;
create function public.post_financial(p_project uuid,p_command jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare correction uuid; correction_reason text; e uuid; prior public.financial_events; kind text:=p_command->>'type'; key uuid:=(p_command->>'idempotency_key')::uuid; hash text:=encode(extensions.digest(p_command::text,'sha256'),'hex'); src uuid:=(p_command->>'source_id')::uuid; n bigint:=coalesce((p_command->>'amount_minor')::bigint,0); cash uuid:=(p_command->>'account_id')::uuid; counter uuid; cat uuid:=(p_command->>'category_id')::uuid; who uuid:=(p_command->>'member_user_id')::uuid; pur public.purchases; bill public.bills; claim public.reimbursement_claims; adv public.advances; a record; left_to_pay bigint; part bigint; amount bigint; base text; dt date:=coalesce((p_command->>'date')::date,current_date); r jsonb; old public.financial_events; dest text;
begin
perform private.assert_finance(p_project);
perform 1 from public.projects where id=p_project for update;
select * into prior from public.financial_events where project_id=p_project and idempotency_key=key;
if prior.id is not null then if prior.command_hash<>hash then raise exception 'IDEMPOTENCY_CONFLICT'; end if; return prior.id; end if;
select currency,status into base,dest from public.projects where id=p_project;
if kind='PURCHASE' then select corrects_event_id,notes into correction,correction_reason from public.purchases where id=src and project_id=p_project; elsif kind='BILL' then select corrects_event_id,notes into correction,correction_reason from public.bills where id=src and project_id=p_project; end if;
if correction is not null and (length(coalesce(correction_reason,''))<5 or not exists(select 1 from public.financial_events where id=correction and project_id=p_project and status='REVERSED' and event_type=kind)) then raise exception 'INVALID_CORRECTION'; end if;
if dest in ('closed','archived') and not((kind='REVERSAL' or correction is not null) and private.role(p_project,array['OWNER','ADMIN']::public.project_role[])) then raise exception 'PROJECT_CLOSED'; end if;
if key is null or kind not in ('FUNDING','PURCHASE','BILL','BILL_PAYMENT','REIMBURSEMENT','ADVANCE','ADVANCE_TOPUP','ADVANCE_RETURN','REFUND','TRANSFER','REVERSAL','ADJUSTMENT','RECOVERY','NONREIMBURSABLE','VENDOR_CREDIT') then raise exception 'INVALID_COMMAND'; end if;
if cash is not null and not exists(select 1 from public.financial_accounts where id=cash and project_id=p_project and account_type in ('BANK','CASH','WALLET') and currency=base and is_active) then raise exception 'INVALID_CASH_ACCOUNT'; end if;
if kind in ('FUNDING','BILL_PAYMENT','REIMBURSEMENT','ADVANCE','ADVANCE_TOPUP','ADVANCE_RETURN','TRANSFER','RECOVERY') and (cash is null or n<=0) then raise exception 'INVALID_AMOUNT_ACCOUNT'; end if;
if kind='PURCHASE' then select total_minor,purchase_date into n,dt from public.purchases where id=src and project_id=p_project; end if;
if kind='BILL' then select total_minor,issue_date into n,dt from public.bills where id=src and project_id=p_project; end if;
if kind in ('PURCHASE','BILL','ADVANCE','ADVANCE_TOPUP') and not private.approval_ready(p_project,case kind when 'PURCHASE' then 'purchases' when 'BILL' then 'bills' else 'advances' end,src,n) then raise exception 'APPROVAL_REQUIRED'; end if;
insert into public.financial_events(project_id,event_type,event_date,description,reference_number,created_by,posted_by,source_id,metadata,idempotency_key,command_hash,reverses_event_id,corrects_event_id) values(p_project,kind,dt,coalesce(nullif(p_command->>'description',''),replace(kind,'_',' ')),p_command->>'reference',auth.uid(),auth.uid(),src,p_command-'idempotency_key',key,hash,case when kind='REVERSAL' then src else null end,correction) returning id into e;
if kind in ('PURCHASE','BILL','ADVANCE','ADVANCE_TOPUP') then update public.approval_instances set posted_event_id=e where project_id=p_project and entity_id=src and entity_type=case kind when 'PURCHASE' then 'purchases' when 'BILL' then 'bills' else 'advances' end and status='approved' and approved_amount_minor=n and posted_event_id is null; end if;
case kind
when 'FUNDING' then
if src is null or not exists(select 1 from public.funding_sources where id=src and project_id=p_project and currency=base) then raise exception 'FUNDING_SOURCE_REQUIRED'; end if;
perform private.entry(p_project,e,cash,'DEBIT',n); perform private.entry(p_project,e,private.account(p_project,'FUNDING'),'CREDIT',n);
insert into public.funding_tranches(project_id,funding_source_id,financial_event_id,amount_minor,received_at) values(p_project,src,e,n,dt);
when 'PURCHASE' then
select * into pur from public.purchases where id=src and project_id=p_project for update; if pur.id is null or pur.status not in ('draft','approved','needs_info') or pur.bill_id is not null then raise exception 'PURCHASE_NOT_POSTABLE'; end if;
if pur.total_minor<>(select coalesce(sum(amount_minor),0) from public.purchase_funding_allocations where purchase_id=src) then raise exception 'ALLOCATION_MISMATCH'; end if;
if exists(select 1 from public.bills where project_id=p_project and vendor_id is not distinct from pur.vendor_id and lower(trim(invoice_number))=lower(trim(pur.invoice_number)) and status<>'cancelled') then raise exception 'INVOICE_ALREADY_BILLED'; end if;
if pur.linked_request_id is not null and not exists(select 1 from public.purchase_requests where id=pur.linked_request_id and project_id=p_project and status='approved') then raise exception 'REQUEST_NOT_APPROVED'; end if;
for a in select category_id,sum(value)::bigint value from (select category_id,line_total_minor value from public.purchase_items where purchase_id=src union all select pur.category_id,pur.shipping_minor) costs group by category_id loop if a.value>0 then perform private.budget_check(p_project,a.category_id,a.value,pur.purchase_date,pur.linked_request_id); end if; end loop;
for a in select * from public.purchase_funding_allocations where purchase_id=src order by id for update loop
if a.currency<>base then raise exception 'CURRENCY_MISMATCH'; end if;
case a.source_type
when 'PROJECT_ACCOUNT' then counter:=a.project_account_id; if not exists(select 1 from public.financial_accounts where id=counter and account_type in ('BANK','CASH','WALLET') and is_active) then raise exception 'INVALID_ACCOUNT'; end if;
when 'MEMBER' then counter:=private.account(p_project,'MEMBER_PAYABLE',a.member_user_id);
when 'ADVANCE' then select * into adv from public.advances where id=a.advance_id for update; if private.advance_balance(a.advance_id)<a.amount_minor then raise exception 'ADVANCE_EXCEEDED'; end if; counter:=private.account(p_project,'ADVANCE',adv.member_user_id); insert into public.advance_expense_links(project_id,advance_id,purchase_funding_allocation_id,amount_minor) values(p_project,a.advance_id,a.id,a.amount_minor);
when 'EXTERNAL' then counter:=private.account(p_project,'EXTERNAL');
end case;
perform private.entry(p_project,e,counter,'CREDIT',a.amount_minor);
end loop;
for a in select category_id,sum(line_total_minor)::bigint as value from public.purchase_items where purchase_id=src group by category_id loop if a.value>0 then perform private.entry(p_project,e,private.account(p_project,'EXPENSE'),'DEBIT',a.value,a.category_id); end if; end loop;
if pur.shipping_minor>0 then perform private.entry(p_project,e,private.account(p_project,'EXPENSE'),'DEBIT',pur.shipping_minor,pur.category_id); end if;
update public.purchases set status='posted',financial_event_id=e where id=src;
insert into public.assets(project_id,purchase_item_id,name,purchase_value_minor,currency,purchase_date) select p_project,id,description,line_total_minor,base,pur.purchase_date from public.purchase_items where purchase_id=src and mark_as_asset;
when 'BILL' then
select * into bill from public.bills where id=src and project_id=p_project for update; if bill.id is null or bill.status not in ('draft','approved') then raise exception 'BILL_NOT_POSTABLE'; end if;
if exists(select 1 from public.purchases where project_id=p_project and vendor_id is not distinct from bill.vendor_id and lower(trim(invoice_number))=lower(trim(bill.invoice_number)) and status='posted') then raise exception 'INVOICE_ALREADY_PURCHASED'; end if;
if bill.linked_request_id is not null and not exists(select 1 from public.purchase_requests where id=bill.linked_request_id and project_id=p_project and status='approved') then raise exception 'REQUEST_NOT_APPROVED'; end if;
perform private.budget_check(p_project,bill.category_id,bill.total_minor,bill.issue_date,bill.linked_request_id);
perform private.entry(p_project,e,private.account(p_project,'EXPENSE'),'DEBIT',bill.total_minor,bill.category_id); perform private.entry(p_project,e,private.account(p_project,'VENDOR_PAYABLE'),'CREDIT',bill.total_minor);
update public.bills set status='unpaid',financial_event_id=e where id=src;
when 'BILL_PAYMENT' then
select * into bill from public.bills where id=src and project_id=p_project for update; if bill.id is null or n>private.bill_balance(src) then raise exception 'PAYMENT_EXCEEDS_OUTSTANDING'; end if;
perform private.entry(p_project,e,private.account(p_project,'VENDOR_PAYABLE'),'DEBIT',n); perform private.entry(p_project,e,cash,'CREDIT',n);
insert into public.bill_payments(project_id,bill_id,project_account_id,amount_minor,reference,financial_event_id) values(p_project,src,cash,n,p_command->>'reference',e);
update public.bills set status=case when private.bill_balance(src)=0 then 'paid' else 'partially_paid' end where id=src;
when 'REIMBURSEMENT' then
select * into claim from public.reimbursement_claims where id=src and project_id=p_project for update; if claim.id is null or claim.status not in ('approved','partially_paid','payment_pending') then raise exception 'CLAIM_NOT_APPROVED'; end if;
if n>private.claim_balance(src) then raise exception 'PAYMENT_EXCEEDS_OUTSTANDING'; end if;
left_to_pay:=n;
for a in select ci.*,f.amount_minor from public.reimbursement_claim_items ci join public.purchase_funding_allocations f on f.id=ci.purchase_funding_allocation_id where ci.reimbursement_claim_id=src order by ci.id for update of f loop part:=least(left_to_pay,private.source_outstanding(a.purchase_funding_allocation_id),a.claimed_minor-coalesce((select sum(sa.amount_minor) from public.settlement_allocations sa join public.financial_events fe on fe.id=sa.event_id where sa.source_allocation_id=a.purchase_funding_allocation_id and sa.kind='PAYMENT' and fe.source_id=src and fe.status='POSTED'),0)); if part>0 then insert into public.settlement_allocations(project_id,event_id,source_allocation_id,kind,amount_minor) values(p_project,e,a.purchase_funding_allocation_id,'PAYMENT',part); left_to_pay:=left_to_pay-part; end if; end loop;
if left_to_pay<>0 then raise exception 'ENTITLEMENT_EXCEEDED'; end if;
perform private.entry(p_project,e,private.account(p_project,'MEMBER_PAYABLE',claim.claimant_user_id),'DEBIT',n); perform private.entry(p_project,e,cash,'CREDIT',n);
insert into public.reimbursement_payments(project_id,reimbursement_claim_id,project_account_id,amount_minor,reference,financial_event_id,paid_by_user_id) values(p_project,src,cash,n,p_command->>'reference',e,auth.uid());
update public.reimbursement_claims set status=case when private.claim_balance(src)=0 then 'paid' else 'partially_paid' end where id=src;
when 'ADVANCE','ADVANCE_TOPUP' then
select * into adv from public.advances where id=src and project_id=p_project for update; if adv.requested_minor>0 and n<>adv.requested_minor then raise exception 'ADVANCE_REQUEST_AMOUNT_MISMATCH'; end if; if adv.id is null or adv.status='closed' or (kind='ADVANCE' and adv.financial_event_id is not null) then raise exception 'INVALID_ADVANCE'; end if;
perform private.entry(p_project,e,private.account(p_project,'ADVANCE',adv.member_user_id),'DEBIT',n); perform private.entry(p_project,e,cash,'CREDIT',n);
update public.advances set issued_minor=issued_minor+n,status='issued',issued_at=now(),project_account_id=cash,financial_event_id=coalesce(financial_event_id,e) where id=src;
when 'ADVANCE_RETURN' then
select * into adv from public.advances where id=src and project_id=p_project for update; if adv.id is null or n>private.advance_balance(src) then raise exception 'ADVANCE_EXCEEDED'; end if;
perform private.entry(p_project,e,cash,'DEBIT',n); perform private.entry(p_project,e,private.account(p_project,'ADVANCE',adv.member_user_id),'CREDIT',n);
insert into public.advance_returns(project_id,advance_id,amount_minor,financial_event_id,reference) values(p_project,src,n,e,p_command->>'reference');
when 'TRANSFER' then
counter:=(p_command->>'destination_account_id')::uuid; if counter=cash or not exists(select 1 from public.financial_accounts where id=counter and project_id=p_project and account_type in ('BANK','CASH','WALLET') and is_active) then raise exception 'INVALID_DESTINATION'; end if;
perform private.entry(p_project,e,counter,'DEBIT',n); perform private.entry(p_project,e,cash,'CREDIT',n);
when 'REFUND' then
select * into pur from public.purchases where id=src and project_id=p_project and status='posted' for update;
if pur.id is null then raise exception 'REFUND_SOURCE_REQUIRED'; end if;
if n<=0 or n>pur.total_minor-coalesce((select sum(rr.amount_minor) from public.refunds rr join public.financial_events fe on fe.id=rr.financial_event_id where rr.purchase_id=src and fe.status='POSTED'),0) then raise exception 'REFUND_EXCEEDED'; end if;
left_to_pay:=0;
for r in select * from jsonb_array_elements(p_command->'allocations') loop amount:=(r->>'amount_minor')::bigint; left_to_pay:=left_to_pay+amount; dest:=r->>'destination';
if dest='PROJECT_ACCOUNT' then counter:=(r->>'account_id')::uuid; if not exists(select 1 from public.financial_accounts where id=counter and project_id=p_project and account_type in ('BANK','CASH','WALLET')) then raise exception 'INVALID_DESTINATION'; end if; perform private.entry(p_project,e,counter,'DEBIT',amount);
elsif dest='MEMBER' then select * into a from public.purchase_funding_allocations where id=(r->>'allocation_id')::uuid and purchase_id=src and source_type='MEMBER' for update; if not found then raise exception 'INVALID_REFUND_MEMBER'; end if; if amount>a.amount_minor-coalesce((select sum((ra->>'amount_minor')::bigint) from public.refunds rr join public.financial_events fe on fe.id=rr.financial_event_id cross join lateral jsonb_array_elements(rr.allocations) ra where rr.purchase_id=src and fe.status='POSTED' and ra->>'allocation_id'=a.id::text),0) then raise exception 'REFUND_EXCEEDED'; end if; part:=least(amount,greatest(0,private.source_outstanding(a.id))); if part>0 then perform private.entry(p_project,e,private.account(p_project,'MEMBER_PAYABLE',a.member_user_id),'DEBIT',part); insert into public.settlement_allocations(project_id,event_id,source_allocation_id,kind,amount_minor) values(p_project,e,a.id,'REFUND',part); end if; if amount>part then perform private.entry(p_project,e,private.account(p_project,'MEMBER_RECOVERY',a.member_user_id),'DEBIT',amount-part); end if;
elsif dest='ADVANCE' then select * into adv from public.advances where id=(r->>'advance_id')::uuid and project_id=p_project for update; if adv.id is null or adv.status='closed' or not exists(select 1 from public.purchase_funding_allocations where purchase_id=src and advance_id=adv.id) then raise exception 'INVALID_ADVANCE'; end if; if amount>coalesce((select sum(amount_minor) from public.purchase_funding_allocations where purchase_id=src and advance_id=adv.id),0)-coalesce((select sum((ra->>'amount_minor')::bigint) from public.refunds rf join public.financial_events fe on fe.id=rf.financial_event_id cross join lateral jsonb_array_elements(rf.allocations) ra where rf.purchase_id=src and fe.status='POSTED' and ra->>'advance_id'=adv.id::text),0) then raise exception 'REFUND_EXCEEDED'; end if; perform private.entry(p_project,e,private.account(p_project,'ADVANCE',adv.member_user_id),'DEBIT',amount);
elsif dest='EXTERNAL' then if amount>coalesce((select sum(amount_minor) from public.purchase_funding_allocations where purchase_id=src and source_type='EXTERNAL'),0)-coalesce((select sum((ra->>'amount_minor')::bigint) from public.refunds rf join public.financial_events fe on fe.id=rf.financial_event_id cross join lateral jsonb_array_elements(rf.allocations) ra where rf.purchase_id=src and fe.status='POSTED' and ra->>'destination'='EXTERNAL'),0) then raise exception 'REFUND_EXCEEDED'; end if; if not exists(select 1 from public.purchase_funding_allocations where purchase_id=src and source_type='EXTERNAL') then raise exception 'INVALID_EXTERNAL'; end if; perform private.entry(p_project,e,private.account(p_project,'EXTERNAL'),'DEBIT',amount);
else raise exception 'INVALID_REFUND_DESTINATION'; end if;
end loop;
if left_to_pay<>n then raise exception 'ALLOCATION_MISMATCH'; end if;
perform private.entry(p_project,e,private.account(p_project,'EXPENSE'),'CREDIT',n,pur.category_id);
insert into public.refunds(project_id,purchase_id,amount_minor,financial_event_id,allocations) values(p_project,src,n,e,p_command->'allocations');
when 'VENDOR_CREDIT' then
select * into bill from public.bills where id=src and project_id=p_project for update; if bill.id is null or n<=0 or n>private.bill_balance(src) then raise exception 'CREDIT_EXCEEDS_OUTSTANDING'; end if; perform private.entry(p_project,e,private.account(p_project,'VENDOR_PAYABLE'),'DEBIT',n); perform private.entry(p_project,e,private.account(p_project,'EXPENSE'),'CREDIT',n,bill.category_id); insert into public.refunds(project_id,bill_id,amount_minor,financial_event_id,allocations) values(p_project,src,n,e,'[]');
when 'NONREIMBURSABLE' then
if length(coalesce(p_command->>'reason',''))<5 then raise exception 'REASON_REQUIRED'; end if; select * into a from public.purchase_funding_allocations where id=src and project_id=p_project and source_type='MEMBER' for update; if not found or n<=0 or n>private.source_outstanding(src) then raise exception 'ENTITLEMENT_EXCEEDED'; end if; if exists(select 1 from public.reimbursement_claim_items ci join public.reimbursement_claims cl on cl.id=ci.reimbursement_claim_id where ci.purchase_funding_allocation_id=src and cl.status not in ('rejected','voided','paid')) then raise exception 'ENTITLEMENT_RESERVED'; end if; perform private.entry(p_project,e,private.account(p_project,'MEMBER_PAYABLE',a.member_user_id),'DEBIT',n); perform private.entry(p_project,e,private.account(p_project,'FUNDING'),'CREDIT',n); insert into public.settlement_allocations(project_id,event_id,source_allocation_id,kind,amount_minor) values(p_project,e,src,'NONREIMBURSABLE',n);
when 'RECOVERY' then
counter:=private.account(p_project,'MEMBER_RECOVERY',who); if who is null or n>private.account_balance(counter) then raise exception 'RECOVERY_EXCEEDED'; end if; perform private.entry(p_project,e,cash,'DEBIT',n); perform private.entry(p_project,e,counter,'CREDIT',n);
when 'ADJUSTMENT' then
if not private.role(p_project,array['OWNER','ADMIN']::public.project_role[]) or length(coalesce(p_command->>'reason',''))<5 then raise exception 'REASON_REQUIRED'; end if;
for r in select * from jsonb_array_elements(p_command->'entries') loop perform private.entry(p_project,e,(r->>'account_id')::uuid,r->>'direction',(r->>'amount_minor')::bigint,(r->>'category_id')::uuid); end loop;
when 'REVERSAL' then
if length(coalesce(p_command->>'reason',''))<5 then raise exception 'REASON_REQUIRED'; end if;
select * into old from public.financial_events where id=src and project_id=p_project and status='POSTED' for update; if old.id is null or old.event_type='REVERSAL' then raise exception 'INVALID_REVERSAL'; end if;
if old.event_type='PURCHASE' and (exists(select 1 from public.settlement_allocations s join public.purchase_funding_allocations f on f.id=s.source_allocation_id join public.financial_events fe on fe.id=s.event_id where f.purchase_id=old.source_id and fe.status='POSTED') or exists(select 1 from public.refunds r join public.financial_events fe on fe.id=r.financial_event_id where r.purchase_id=old.source_id and fe.status='POSTED')) then raise exception 'REVERSE_DEPENDENCIES_FIRST'; end if;
if old.event_type='BILL' and private.bill_balance(old.source_id)<>(select total_minor from public.bills where id=old.source_id) then raise exception 'REVERSE_DEPENDENCIES_FIRST'; end if;
if old.event_type in ('ADVANCE','ADVANCE_TOPUP') and private.advance_balance(old.source_id)<(old.metadata->>'amount_minor')::bigint then raise exception 'REVERSE_DEPENDENCIES_FIRST'; end if;
for a in select l.account_id,sum(l.amount_minor)::bigint amount_minor,fa.account_type from public.ledger_entries l join public.financial_accounts fa on fa.id=l.account_id where l.financial_event_id=src and l.direction='DEBIT' and fa.account_type in ('BANK','CASH','WALLET','MEMBER_RECOVERY') group by l.account_id,fa.account_type loop if private.account_balance(a.account_id)<a.amount_minor then raise exception 'REVERSE_DEPENDENCIES_FIRST'; end if; end loop;
if old.event_type='REFUND' then for r in select * from jsonb_array_elements(old.metadata->'allocations') loop if r->>'destination'='ADVANCE' and private.advance_balance((r->>'advance_id')::uuid)<(r->>'amount_minor')::bigint then raise exception 'REVERSE_DEPENDENCIES_FIRST'; end if; end loop; end if;
insert into public.ledger_entries(project_id,financial_event_id,account_id,direction,amount_minor,currency,category_id,memo) select p_project,e,account_id,case direction when 'DEBIT' then 'CREDIT' else 'DEBIT' end,amount_minor,currency,category_id,'Reversal' from public.ledger_entries where financial_event_id=src;
update public.financial_events set status='REVERSED' where id=src;
if old.event_type='PURCHASE' then update public.purchases set status='voided' where id=old.source_id; end if;
if old.event_type='BILL' then update public.bills set status='cancelled' where id=old.source_id; end if;
if old.event_type='BILL_PAYMENT' then update public.bills set status=case when private.bill_balance(old.source_id)=0 then 'paid' when private.bill_balance(old.source_id)=total_minor then 'unpaid' else 'partially_paid' end where id=old.source_id; end if;
if old.event_type='REIMBURSEMENT' then update public.reimbursement_claims set status=case when exists(select 1 from public.reimbursement_payments rp join public.financial_events fe on fe.id=rp.financial_event_id where rp.reimbursement_claim_id=old.source_id and fe.status='POSTED') then 'partially_paid' else 'approved' end where id=old.source_id; end if;
end case;
if not exists(select 1 from public.ledger_entries where financial_event_id=e) then raise exception 'EMPTY_EVENT'; end if;
update public.reimbursement_claims cl set status=case when private.claim_balance(cl.id)=0 then 'paid' when exists(select 1 from public.reimbursement_payments rp join public.financial_events fe on fe.id=rp.financial_event_id where rp.reimbursement_claim_id=cl.id and fe.status='POSTED') then 'partially_paid' else 'approved' end where cl.project_id=p_project and cl.status in ('approved','partially_paid','paid') and cl.approved_minor>0;
perform private.log(p_project,lower(kind)||'_posted','financial_events',e,coalesce(p_command->>'reason',correction_reason)); return e;
end $$;
revoke all on function public.save_purchase(uuid,jsonb),public.post_financial(uuid,jsonb) from public;
grant execute on function public.save_purchase(uuid,jsonb),public.post_financial(uuid,jsonb) to authenticated;
